点击/输入事件:
{"onClick":"() => {
                      if (!shakeProduct) return
                      closeSheet('product_action')
                      onInteraction?.('recommendation_shake_product_opened', { productId: shakeProduct.id })
                      onOpenProduct(shakeProduct)
                    }"}

{"onClick":"() => {
                      if (!shakeProduct) return
                      closeSheet('product_action')
                      onInteraction?.('recommendation_shake_product_chosen', { productId: shakeProduct.id })
                      onChooseProduct(shakeProduct)
                    }"}

{"onClick":"() => {
                if (guestSalesMode) changeGuestMenuView(category.id as typeof guestMenuViews[number]['id'])
                else {
                  setCategoryId(category.id)
                  emitInteraction('category_viewed', { categoryId: category.id })
                }
              }"}

{"onClick":"() => {
              removeProduct(upgradeSourceProduct.id)
              void setProductQuantity(upgradeProduct.id, 1)
              emitInteraction('upgrade_accepted', {
                productId: upgradeProduct.id,
                metadata: { fromProductId: upgradeSourceProduct.id },
              })
              setUpgradePromptProductId('')
              setUpgradeSourceProductId('')
            }"}

{"onClick":"() => {
              if (confirmation === 'continue') void confirmContinuation()
              else void executeSubmit(confirmation === 'duplicate' ? confirmedDuplicateOrderId : undefined)
            }"}

禁用条件:
isMenuConfirmationDisabled({
              busy: checkoutBusy,
              submitDisabled,
              confirmation,
              confirmedDuplicateOrderId,
            })

点击/输入事件:
{"onClick":"() => setCancellationDraft({
                          orderId: order.id,
                          reasonCode: 'guest_left',
                          reasonNote: '',
                          confirmed: false,
                        })"}

{"onChange":"(event) => setCancellationDraft({
                            ...cancellationDraft,
                            reasonCode: event.target.value as CancellationDraft['reasonCode'],
                            confirmed: false,
                          })"}

{"onClick":"() => setSettlementExceptionDraft({
                          orderId: order.id,
                          reasonCode: 'manager_comp',
                          reasonNote: '',
                          confirmed: false,
                        })"}

{"onChange":"(event) => setSettlementExceptionDraft({
                            ...settlementExceptionDraft,
                            reasonCode: event.target.value as SettlementExceptionDraft['reasonCode'],
                            confirmed: false,
                          })"}

{"onClick":"() => void onMutation(
                  `activity-late-success-refund-${registration.id}-${lateSuccessPayment.publicId}`,
                  `/api/staff/community-activity-registrations/${encodeURIComponent(registration.publicId)}/refunds`,
                  { paymentPublicId: lateSuccessPayment.publicId, reason: refundReason.trim() },
                  '旧报名的延迟到账退款申请已提交，等待非申请人复核。',
                )"}

{"onClick":"() => void onMutation(
              `activity-recollection-authorize-${registration.id}`,
              `/api/activity-registrations/${encodeURIComponent(registration.publicId)}/recollection-authorizations`,
              { reason: recollectionReason.trim() },
              '已授权一次活动重新收款；实际收款前仍会重新占用名额和库存。',
            )"}

{"onClick":"() => void onMutation(
            `activity-refund-request-${registration.id}`,
            `/api/staff/community-activity-registrations/${encodeURIComponent(registration.publicId)}/refunds`,
            { reason: refundReason.trim() },
            '活动退款申请已提交，等待非申请人复核。',
          )"}

{"onClick":"() => void onMutation(
          `payment-provider-query-${payment.id}`,
          `/api/payments/${encodeURIComponent(payment.id)}/provider-query`,
          {},
          '已完成渠道查单，结果已按渠道回传更新。',
        )"}

{"onClick":"() => void onMutation(
            `refund-provider-query-${refund.id}`,
            `/api/refunds/${encodeURIComponent(refund.id)}/provider-query`,
            {},
            '已完成退款渠道查询，结果已按渠道回传更新。',
          )"}

{"onClick":"() => void onMutation(
            `refund-reject-${refund.id}`,
            `/api/refunds/${encodeURIComponent(refund.id)}/reject`,
            { reason: decisionReason },
            '退款申请已驳回，可由申请人更正后重新提交。',
          )"}

{"onClick":"() => void onMutation(
            `refund-approve-${refund.id}`,
            `/api/refunds/${encodeURIComponent(refund.id)}/approve`,
            { reason: decisionReason },
            manualProvider ? '退款已复核通过，请在线下实际退还后登记独立凭证；系统不会自动转账。' : '退款已复核通过，系统会自动向原支付渠道提交并核对结果，无需再次点击执行。',
          )"}

{"onClick":"() => void onMutation(
            `refund-provider-query-${refund.id}`,
            `/api/refunds/${encodeURIComponent(refund.id)}/provider-query`,
            {},
            '已查询渠道退款结果。',
          )"}

{"onClick":"() => {
              const succeeded = manualConfirmation === 'succeeded'
              setManualConfirmation(null)
              void onMutation(
                `refund-manual-${succeeded ? 'success' : 'failed'}-${refund.id}`,
                `/api/refunds/${encodeURIComponent(refund.id)}/manual-result`,
                { succeeded, ...(payment.provider === 'cash' ? {} : { receiptReference: manualReceipt }) },
                succeeded ? '人工退款凭证已登记并写入退款账。' : '已登记人工退款失败，金额未记入退款账。',
              )
            }"}

{"onChange":"event => {
    const input = event.currentTarget
    setText(input.value)
    const minor = yuanInputToMinor(input.value)
    input.setCustomValidity(minor === null ? '请输入金额，最多两位小数' : '')
    if (minor !== null) onChange(minor)
  }"}

{"onChange":"(event) => {
              const selected = overview.payrollRuns.find((item) => item.id === event.target.value);
              if (selected) { setEditingPayrollLine(null); setPayroll((value) => ({ ...value, periodStart: selected.periodStart, periodEnd: selected.periodEnd })); }
            }"}

{"onClick":"() => {
                        selectTable(table, false)
                        secondaryTableSessionIdRef.current = table.activeSession?.id ?? null
                        setTablePaymentOpen(true)
                      }"}

{"onChange":"(event) => {
            const next = toggleValue(values, option.value, event.target.checked)
            updateScope(definition, { value: next, enabled: next.length > 0 })
          }"}

{"onClick":"() => {
      setSelected(section.id); setVisited(previous => new Set([...previous, section.id]))
      const hash = new URLSearchParams(window.location.hash.slice(1)); hash.set('work', section.id)
      window.history.replaceState(window.history.state, '', `${window.location.pathname}${window.location.search}#${hash}`)
    }"}
